import {normalizePuzzle} from './fire-puzzle.js';
export const caveEntrance={x:-57,z:7};
export const dock={x:0,z:23};
export const BOAT_COST={wood:30,stone:12,iron:4};
export const MAZE_SIZE=25,CELL=3;
export function makeMaze(seed=721){const grid=Array.from({length:MAZE_SIZE},()=>Array(MAZE_SIZE).fill(1));let n=seed>>>0;const random=()=>{n=(1664525*n+1013904223)>>>0;return n/4294967296;};grid[1][1]=0;const stack=[[1,1]];while(stack.length){const[x,z]=stack.at(-1),options=[[2,0],[-2,0],[0,2],[0,-2]].filter(([dx,dz])=>x+dx>0&&z+dz>0&&x+dx<MAZE_SIZE-1&&z+dz<MAZE_SIZE-1&&grid[z+dz][x+dx]);if(!options.length){stack.pop();continue;}const[dx,dz]=options[Math.floor(random()*options.length)];grid[z+dz/2][x+dx/2]=0;grid[z+dz][x+dx]=0;stack.push([x+dx,z+dz]);}return grid;}
export const maze=makeMaze();
export function mazeRoute(from,to){const start=[Math.round(from.x/CELL),Math.round(from.z/CELL)],end=[Math.round(to.x/CELL),Math.round(to.z/CELL)],key=(x,z)=>x+','+z;if(maze[start[1]]?.[start[0]]!==0||maze[end[1]]?.[end[0]]!==0)return [];const queue=[start],previous=new Map([[key(...start),null]]);for(let i=0;i<queue.length;i++){const[x,z]=queue[i];if(x===end[0]&&z===end[1]){const route=[];let k=key(x,z);while(k){const[a,b]=k.split(',').map(Number);route.unshift({x:a*CELL,z:b*CELL});k=previous.get(k);}return route;}for(const[dx,dz]of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,nz=z+dz,k=key(nx,nz);if(maze[nz]?.[nx]===0&&!previous.has(k)){previous.set(k,key(x,z));queue.push([nx,nz]);}}}return [];}
export function caveWalkable(x,z,r=.28){return [[-r,-r],[-r,r],[r,-r],[r,r]].every(([dx,dz])=>maze[Math.round((z+dz)/CELL)]?.[Math.round((x+dx)/CELL)]===0);}
export function savannaHeight(x,z){return .45*Math.sin(x*.025)*Math.cos(z*.03);}
export function savannaWalkable(x,z){return Math.hypot(x,z)<145;}
export const journeySpecies=[{id:'ember',name:'Pyrosaure des cristaux',world:'cave',cost:12,x:69,z:69,kind:'fire',color:0xb76655},{id:'elephant',name:'Éléphant',world:'africa',cost:10,x:-30,z:15,kind:'elephant',color:0x97958e},{id:'giraffe',name:'Girafe',world:'africa',cost:8,x:25,z:-22,kind:'giraffe',color:0xd1aa56},{id:'zebra',name:'Zèbre',world:'africa',cost:6,x:16,z:26,kind:'zebra',color:0xe8e3cd},{id:'lion',name:'Lion',world:'africa',cost:10,x:-55,z:-35,kind:'lion',color:0xc19a54}];
for(const base of journeySpecies.slice(1))for(let i=1;i<=3;i++)journeySpecies.push({...base,id:base.id+'-'+i,x:base.x+(i%2?1:-1)*(15+i*9),z:base.z+(i-2)*22});
export function normalizeJourney(value={}){const old=value&&typeof value==='object'?value:{};return {puzzle:normalizePuzzle(old.puzzle),version:1,treasure:old.treasure===true,seen:[...new Set((Array.isArray(old.seen)?old.seen:[]).filter(kind=>journeySpecies.some(s=>s.kind===kind)))],visited:{cave:old.visited?.cave===true,africa:old.visited?.africa===true},animals:Object.fromEntries(journeySpecies.map(s=>{const a=old.animals?.[s.id]||{},valid=Number.isFinite(a.x)&&Number.isFinite(a.z)&&(s.world==='cave'?caveWalkable(a.x,a.z):savannaWalkable(a.x,a.z));return [s.id,{tame:a.tame===true,refuge:a.tame===true&&a.refuge===true,feed:Math.max(0,Math.min(s.cost-1,Math.floor(Number(a.feed)||0))),nickname:typeof a.nickname==='string'?a.nickname.slice(0,20):'',order:a.order==='stay'?'stay':'follow',x:valid?a.x:s.x,z:valid?a.z:s.z}];})),harvests:Object.fromEntries(Object.entries(old.harvests||{}).filter(([k,v])=>/^tree-\d+$/.test(k)&&Number.isFinite(v)&&v>0).map(([k,v])=>[k,Math.min(60,v)]))};}
export function feedJourneyAnimal(d,inv,hasRoom){if(d.tame)return 'friend';if(d.feed+1>=d.s.cost&&!hasRoom)return 'full';if(!(inv.berries>0))return 'empty';inv.berries--;d.feed++;if(d.feed>=d.s.cost){d.tame=true;d.feed=0;d.order='follow';return 'tamed';}return 'fed';}
export function claimCaveTreasure(state,inv){if(state.treasure)return false;state.treasure=true;inv.gems=(inv.gems||0)+40;return true;}
